require_once __DIR__.'/../includes/authorization.php';require_role('admin');$rows=db()->query("SELECT status, COUNT(*) total FROM orders GROUP BY status ORDER BY status")->fetchAll();$byCategory=db()->query("SELECT category, COUNT(*) total FROM products GROUP BY category ORDER BY total DESC")->fetchAll();$sold=(int)db()->query("SELECT COALESCE(SUM(quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status='completed'")->fetchColumn();$totalOrders=(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn();$revenue=(int)db()->query("SELECT COALESCE(SUM(line_total),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status='completed'")->fetchColumn();
$pageTitle='Laporan';require __DIR__.'/../includes/header.php';
?><section class="section-padding page-section"><div class="container"><div class="page-toolbar"><?=back_link('admin-dashboard','Kembali ke dashboard admin')?></div><div class="section-heading mb-4"><span class="eyebrow">Admin</span><h2>Laporan <em>sederhana.</em></h2><p class="text-muted">Semua angka berasal dari data transaksi dan katalog aktual.</p></div><div class="row g-4"><div class="col-md-4"><div class="glass-card p-4"><span class="eyebrow">Produk terjual</span><h2><?=$sold?></h2></div></div><div class="col-md-4"><div class="glass-card p-4"><span class="eyebrow">Transaksi</span><h2><?=$totalOrders?></h2></div></div><div class="col-md-4"><div class="glass-card p-4"><span class="eyebrow">Nilai selesai</span><h2><?=format_price($revenue)?></h2></div></div></div><div class="row g-4 mt-2"><div class="col-md-6"><div class="glass-card p-4"><h3 class="h5">Order per status</h3><?php foreach($rows as $r):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($r['status'])?></span><strong><?=intval($r['total'])?></strong></div><?php endforeach;?></div></div><div class="col-md-6"><div class="glass-card p-4"><h3 class="h5">Produk per kategori</h3><?php foreach($byCategory as $r):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($r['category'])?></span><strong><?=intval($r['total'])?></strong></div><?php endforeach;?></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>